// Game simulation: player movement/collision, hitscan weapons, bot AI with
// waypoint navigation + line-of-sight, CS-style economy and round flow.
// Map data (boxes/waypoints/spawns) is injected per match via startMatch().
// Two modes: 'bots' (solo rounds vs AI) and 'dm' (online deathmatch — remote
// players are hit-tested locally, damage is applied by the server).

export const MAT = {
  FLOOR: 0, BRICK: 1, CRATE: 2, METAL: 3, NEON_A: 4, NEON_B: 5,
  DARKMETAL: 6, PLASTER: 7, CHAR_BODY: 8, CHAR_VISOR: 9, HAZARD: 10, CHAR_CLOTH: 11,
};

