// spheres for the ray tracer (bots + remote players via main.js)
renderSpheres() {
  const out = [];
  for (const b of this.bots) {
    if (!b.alive && b.deathT <= 0) continue;
    const sink = b.alive ? 0 : (1 - b.deathT / 0.6) * 1.6;
    out.push(...characterSpheres(b.pos, b.yaw, false, b.tint, sink));
  }
  return out;
}

