1	// WebGL2 fragment-shader ray tracer. No rasterized geometry: every pixel
2	// casts a primary ray against the analytic scene (AABBs + spheres + capsules
3	// for character limbs), then shadow rays, AO rays, and reflection bounces.
4	// HDR pipeline: scene renders linear HDR to an FBO, a bright-pass + separable
5	// gaussian blur builds bloom, and a composite pass applies ACES + vignette.
6	// Map geometry, lights, and theme are uploaded at runtime via loadMap().
7	
8	const MAX_BOXES = 64;
9	const MAX_SPHERES = 32;
10	const MAX_CAPSULES = 48;
11	const NUM_LIGHTS = 12;
12	const MAX_BOUNCES = 3;
13	
14	const VERT = `#version 300 es
15	layout(location=0) in vec2 aPos;
16	out vec2 vUV;
17	void main(){ vUV = aPos * 0.5 + 0.5; gl_Position = vec4(aPos, 0.0, 1.0); }
18	`;
19	
20	const SCENE_FRAG = `#version 300 es
21	precision highp float;
22	precision highp int;
23	precision highp sampler2D;
24	
25	#define MAX_BOXES ${MAX_BOXES}
26	#define MAX_SPHERES ${MAX_SPHERES}
27	#define MAX_CAPSULES ${MAX_CAPSULES}
28	#define NUM_LIGHTS ${NUM_LIGHTS}
29	#define MAX_BOUNCES ${MAX_BOUNCES}
30	
31	out vec4 outColor;
32	
33	uniform vec2 uRes;
34	uniform float uTime;
35	uniform vec3 uCamPos;
36	uniform vec3 uCamFwd;
37	uniform vec3 uCamRight;
38	uniform vec3 uCamUp;
39	uniform float uTanY;
40	
41	uniform sampler2D uBoxTex;
42	uniform int uNumBoxes;
43	uniform vec4 uSpheres[MAX_SPHERES];     // xyz, r
44	uniform vec4 uSphereMat[MAX_SPHERES];   // mat id, tint rgb
45	uniform int uNumSpheres;
46	uniform vec4 uCapA[MAX_CAPSULES];       // end A xyz, radius
47	uniform vec4 uCapB[MAX_CAPSULES];       // end B xyz, mat id
48	uniform vec3 uCapTint[MAX_CAPSULES];
49	uniform int uNumCaps;
50	
51	uniform vec3 uSunDir;
52	uniform vec3 uSunCol;
53	uniform float uSunInt;
54	uniform vec4 uLightPos[NUM_LIGHTS];
55	uniform vec3 uLightCol[NUM_LIGHTS];
56	
57	uniform vec3 uSkyTop;
58	uniform vec3 uSkyHorizon;
59	uniform vec3 uHaze;
60	uniform vec3 uFogCol;
61	uniform vec3 uNeonA;
62	uniform vec3 uNeonB;
63	
64	uniform int uBounces;
65	uniform int uShadowMode;
66	uniform int uShadowSamples;
67	uniform int uAOMode;
68	uniform int uFog;
69	uniform int uPulse;
70	uniform int uDebugMat;
71	uniform int uDirect;   // 1: tonemap inline and output LDR (no-bloom path)
72	
73	// ---------- hash / noise ----------
74	float hash12(vec2 p){
75	  p = fract(p * vec2(123.34, 456.21));
76	  p += dot(p, p + 45.32);
77	  return fract(p.x * p.y);
78	}
79	float hash13(vec3 p){
80	  p = fract(p * vec3(123.34, 456.21, 789.92));
81	  p += dot(p, p.zyx + 31.32);
82	  return fract((p.x + p.y) * p.z);
83	}
84	float vnoise(vec2 p){
85	  vec2 i = floor(p), f = fract(p);
86	  f = f * f * (3.0 - 2.0 * f);
87	  float a = hash12(i);
88	  float b = hash12(i + vec2(1.0, 0.0));
89	  float c = hash12(i + vec2(0.0, 1.0));
90	  float d = hash12(i + vec2(1.0, 1.0));
91	  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
92	}
93	float fbm(vec2 p){
94	  float v = 0.0, a = 0.5;
95	  for (int i = 0; i < 3; i++){
96	    v += a * vnoise(p);
97	    p = p * 2.13 + vec2(7.7);
98	    a *= 0.5;
99	  }
100	  return v;
101	}
102	
103	// ---------- intersections ----------
104	float iBox(vec3 ro, vec3 rd, vec3 bmin, vec3 bmax, out vec3 n){
105	  vec3 inv = 1.0 / rd;
106	  vec3 t0 = (bmin - ro) * inv;
107	  vec3 t1 = (bmax - ro) * inv;
108	  vec3 tsm = min(t0, t1);
109	  vec3 tbg = max(t0, t1);
110	  float tN = max(max(tsm.x, tsm.y), tsm.z);
111	  float tF = min(min(tbg.x, tbg.y), tbg.z);
112	  if (tN > tF || tF < 0.0) { n = vec3(0.0); return -1.0; }
113	  float t = tN >= 0.0 ? tN : tF;
114	  vec3 axis = step(vec3(tN - 1e-4), tsm);
115	  n = -sign(rd) * axis;
116	  if (tN < 0.0) n = -n;
117	  return t;
118	}
119	float iSphere(vec3 ro, vec3 rd, vec3 c, float r){
120	  vec3 oc = ro - c;
121	  float b = dot(oc, rd);
122	  float cc = dot(oc, oc) - r * r;
123	  float h = b * b - cc;
124	  if (h < 0.0) return -1.0;
125	  float t = -b - sqrt(h);
126	  return t > 0.0 ? t : -1.0;
127	}
128	// iq's capsule intersector
129	float iCapsule(vec3 ro, vec3 rd, vec3 pa, vec3 pb, float r){
130	  vec3 ba = pb - pa;
131	  vec3 oa = ro - pa;
132	  float baba = dot(ba, ba);
133	  float bard = dot(ba, rd);
134	  float baoa = dot(ba, oa);
135	  float rdoa = dot(rd, oa);
136	  float oaoa = dot(oa, oa);
137	  // a >= 0 mathematically; clamp so rays parallel to the axis can't produce
138	  // a near-zero/negative denominator (garbage t -> phantom hits)
139	  float a = max(baba - bard * bard, 1e-5);
140	  float b = baba * rdoa - baoa * bard;
141	  float c = baba * oaoa - baoa * baoa - r * r * baba;
142	  float h = b * b - a * c;
143	  if (h >= 0.0){
144	    float t = (-b - sqrt(h)) / a;
145	    float y = baoa + t * bard;
146	    if (y > 0.0 && y < baba && t > 0.0) return t;
147	    vec3 oc = (y <= 0.0) ? oa : ro - pb;
148	    b = dot(rd, oc);
149	    c = dot(oc, oc) - r * r;
150	    h = b * b - c;
151	    if (h > 0.0){
152	      float t2 = -b - sqrt(h);
153	      if (t2 > 0.0) return t2;
154	    }
155	  }
156	  return -1.0;
157	}
158	vec3 capNormal(vec3 p, vec3 a, vec3 b, float r){
159	  vec3 ba = b - a;
160	  vec3 pa = p - a;
161	  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
162	  return (pa - h * ba) / r;
163	}
164	
165	struct Hit { float t; vec3 n; float mat; vec3 p; vec3 tint; };
166	
167	bool trace(vec3 ro, vec3 rd, float maxT, out Hit h){
168	  h.t = maxT;
169	  h.mat = -1.0;
170	  h.n = vec3(0.0, 1.0, 0.0);
171	  h.tint = vec3(1.0);
172	  int capHit = -1;
173	  for (int i = 0; i < MAX_BOXES; i++){
174	    if (i >= uNumBoxes) break;
175	    vec4 a = texelFetch(uBoxTex, ivec2(i, 0), 0);
176	    vec4 b = texelFetch(uBoxTex, ivec2(i, 1), 0);
177	    vec3 n;
178	    float t = iBox(ro, rd, a.xyz, b.xyz, n);
179	    if (t > 0.001 && t < h.t){ h.t = t; h.n = n; h.mat = a.w; h.tint = vec3(1.0); }
180	  }
181	  for (int i = 0; i < MAX_SPHERES; i++){
182	    if (i >= uNumSpheres) break;
183	    float t = iSphere(ro, rd, uSpheres[i].xyz, uSpheres[i].w);
184	    if (t > 0.001 && t < h.t){
185	      h.t = t;
186	      h.n = normalize(ro + rd * t - uSpheres[i].xyz);
187	      h.mat = uSphereMat[i].x;
188	      h.tint = uSphereMat[i].yzw;
189	    }
190	  }
191	  for (int i = 0; i < MAX_CAPSULES; i++){
192	    if (i >= uNumCaps) break;
193	    float t = iCapsule(ro, rd, uCapA[i].xyz, uCapB[i].xyz, uCapA[i].w);
194	    if (t > 0.001 && t < h.t){ h.t = t; h.mat = uCapB[i].w; h.tint = uCapTint[i]; capHit = i; }
195	  }
196	  if (h.mat < 0.0) return false;
197	  h.p = ro + rd * h.t;
198	  if (capHit >= 0) h.n = capNormal(h.p, uCapA[capHit].xyz, uCapB[capHit].xyz, uCapA[capHit].w);
199	  return true;
200	}
201	
202	bool anyHit(vec3 ro, vec3 rd, float maxT){
203	  for (int i = 0; i < MAX_BOXES; i++){
204	    if (i >= uNumBoxes) break;
205	    vec4 a = texelFetch(uBoxTex, ivec2(i, 0), 0);
206	    vec4 b = texelFetch(uBoxTex, ivec2(i, 1), 0);
207	    vec3 n;
208	    float t = iBox(ro, rd, a.xyz, b.xyz, n);
209	    if (t > 0.001 && t < maxT) return true;
