// Background music: 4-bar synthwave loop — kick, bass saw, pad chords,
// 8th-note arp, offbeat hats. Composed sample-by-sample, loops seamlessly.
function genMusic() {
  const bpm = 92;
  const beat = 60 / bpm;
  const barLen = beat * 4;
  const bars = 4;
  const b = buffer(bars * barLen);
  const chords = [
    [110.00, 130.81, 164.81], // Am
    [87.31, 110.00, 174.61],  // F
    [98.00, 123.47, 146.83],  // G
    [82.41, 123.47, 164.81],  // Em
  ];
  const rnd = makeNoise(777777);
  const n = b.length;
  let bassPhase = 0;
  let arpPhase = 0;
  for (let i = 0; i < n; i++) {
    const t = i / SR;
    const bar = Math.floor(t / barLen) % bars;
    const barT = t - Math.floor(t / barLen) * barLen;
    const chord = chords[bar];
    const beatT = barT % beat;
    const root = chord[0];

    // kick: pitch-swept sine, every beat
    const kick = Math.sin(2 * Math.PI * (48 + 70 * Math.exp(-beatT * 26)) * beatT) * Math.exp(-beatT * 16) * 0.55;

    // bass: saw an octave down, ducked by the kick
    bassPhase += (root / 2) / SR;
    const duck = 1 - 0.7 * Math.exp(-beatT * 14);
    const bass = ((bassPhase % 1) * 2 - 1) * 0.22 * duck;

    // pad: chord sines with a soft per-bar gate (also hides phase resets)
    const gate = Math.min(1, barT * 6, (barLen - barT) * 6);
    let pad = 0;
    for (let c = 0; c < 3; c++) {
      pad += Math.sin(2 * Math.PI * chord[c] * 2 * t) + 0.5 * Math.sin(2 * Math.PI * (chord[c] * 2 + 1.3) * t);
    }
    pad *= 0.045 * gate;

    // arp: 8th notes cycling chord tones two octaves up
    const eighth = Math.floor(barT / (beat / 2));
    const eighthT = barT - eighth * (beat / 2);
    if (eighthT < 1 / SR * 2) arpPhase = 0;
    const arpFreq = chord[eighth % 3] * 4;
    arpPhase += arpFreq / SR;
    const arp = Math.sin(2 * Math.PI * arpPhase) * Math.exp(-eighthT * 9) * 0.13;

    // hats: noise ticks on offbeats
    const offT = (barT + beat / 2) % beat;
    const hat = rnd() * Math.exp(-offT * 70) * 0.09;

    b[i] = kick + bass + pad + arp + hat;
  }
  // crossfade loop seam
  const fade = Math.floor(0.35 * SR);
  for (let i = 0; i < fade; i++) {
    const kf = i / fade;
    b[i] = b[i] * kf + b[b.length - fade + i] * (1 - kf);
  }
  lowpass(b, 7000);
  return normalize(b, 0.4);
}

