# buy menu owns the pointer: open -> release lock so the cards are clickable,
# close -> re-lock for gameplay
old = """    if (phase === 'buy') { buyOpen = true; syncOverlays(); }
    if (phase === 'live') { buyOpen = false; syncOverlays(); }"""
new = """    if (phase === 'buy') setBuyOpen(true);
