assert old in src
src = src.replace(old, new)

old = "else if (e.code === 'KeyB') { buyOpen = !buyOpen; syncOverlays(); }"
new = "else if (e.code === 'KeyB') setBuyOpen(!buyOpen);"
assert old in src
src = src.replace(old, new)

anchor = "let settingsReturnTo = 'menu';"
helper = """function setBuyOpen(open) {
  buyOpen = open;
  syncOverlays();
  if (screen === 'game') {
    if (open) document.exitPointerLock?.();
    else requestPointerLock();
  }
}

let settingsReturnTo = 'menu';"""
assert anchor in src
src = src.replace(anchor, helper)

# don't auto-pause (or fire) while the buy menu intentionally holds the pointer
old = """document.addEventListener('pointerlockchange', () => {
  pointerLocked = document.pointerLockElement === canvas;
  if (!pointerLocked) {
    game.input.fire = false;
    game.input.scope = false;
    if (screen === 'game' && game.state !== 'dead') showScreen('pause');
  }
});"""
new = """document.addEventListener('pointerlockchange', () => {
  pointerLocked = document.pointerLockElement === canvas;
  if (!pointerLocked) {
    game.input.fire = false;
    game.input.scope = false;
    if (screen === 'game' && game.state !== 'dead' && !buyOpen) showScreen('pause');
  }
});"""
assert old in src
